func (this *Coinbaseinternational) watchTickersBody(ch chan ccxt.AsyncResult[map[string]ccxt.Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("watchTickers", params)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsResolved []string = this.MarketSymbols(symbols, nil, false)
	interval, paramsInterval := this.HandleOptionStringAndParams(paramsResolved, "watchTickers", "interval", "100ms")
	var isPrivate bool = (interval != nil && *interval == "raw")
	var channels []any = []any{}
	var symbolsLength int = len(symbolsResolved)
	for i := 0; i < symbolsLength; i++ {
		var market map[string]any = this.Market(this.SafeString(symbolsResolved, i, ""))
		channels = append(channels, "ticker."+*this.SafeString(market, "id", "")+"."+*interval)
	}

	r1 := <-this.SubscribeAsync(channels, channels, isPrivate, paramsInterval)
	if r1.Err != nil {
		panic(r1.Err)
	}
	ticker := r1.Value
	if this.NewUpdates {
		var result map[string]any = map[string]any{}
		var tickerSymbol *string = this.SafeString(ticker, "symbol")
		if tickerSymbol != nil {
			ccxt.AddElementToObject(result, tickerSymbol, ticker)
		}

		ch <- ccxt.AsyncResult[map[string]ccxt.Ticker]{Value: ccxt.TickerMapFromMap(result)}
		return nil
	}

	ch <- ccxt.AsyncResult[map[string]ccxt.Ticker]{Value: this.WsCacheTickerMap("Tickers", symbolsResolved)}
	return nil
}

