func (this *Coinbaseinternational) watchBidsAsksBody(ch chan ccxt.AsyncResult[map[string]ccxt.Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbols []string = ccxt.GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("watchBidsAsks", params)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsResolved []string = this.MarketSymbols(symbols, nil, false)
	var channels []any = []any{}
	var symbolsLength int = len(symbolsResolved)
	for i := 0; i < symbolsLength; i++ {
		var market map[string]any = this.Market(this.SafeString(symbolsResolved, i, ""))
		channels = append(channels, "quote."+*this.SafeString(market, "id", ""))
	}

	r1 := <-this.SubscribeAsync(channels, channels, false, paramsResolved)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var ticker map[string]any = ccxt.MapTyped(r1.Value)
	if this.NewUpdates {
		var result map[string]any = map[string]any{}
		ccxt.AddElementToObject(result, ticker["symbol"], ticker)

		ch <- ccxt.AsyncResult[map[string]ccxt.Ticker]{Value: ccxt.TickerMapFromMap(result)}
		return nil
	}

	ch <- ccxt.AsyncResult[map[string]ccxt.Ticker]{Value: this.WsCacheTickerMap("Bidsasks", symbolsResolved)}
	return nil
}

