func (this *Coinbaseinternational) HandleTicker(client any, message map[string]any) {
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	var ticker map[string]any = ccxt.TickerToMap(this.ParseTicker(data))
	var channel *string = this.SafeString(params, "channel")
	var symbol *string = ccxt.SafeStringPtr(ticker["symbol"])
	this.Tickers.Store(symbol, ticker)
	client.(ccxt.ClientInterface).Resolve(ticker, channel)
}
func (this *Coinbaseinternational) HandleBidAsk(client any, message map[string]any) {
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	var ticker any = this.ParseWsBidAsk(data)
	var symbol *string = this.SafeString(ticker, "symbol")
	this.Bidsasks.Store(symbol, ticker)
	var channel *string = this.SafeString(params, "channel")
	client.(ccxt.ClientInterface).Resolve(ticker, channel)
}
func (this *Coinbaseinternational) ParseWsBidAsk(ticker any, optionalArgs ...any) any {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "instrument_name")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	return ccxt.TickerToMap(this.SafeTicker(map[string]any{
		"info":      ticker,
		"symbol":    marketResolved["symbol"],
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"bid":       this.SafeString(ticker, "best_bid_price"),
		"bidVolume": this.SafeString(ticker, "best_bid_amount"),
		"ask":       this.SafeString(ticker, "best_ask_price"),
		"askVolume": this.SafeString(ticker, "best_ask_amount"),
	}, marketResolved))
}

/**
 * @method
 * @name coinbaseinternational#watchOHLCV
 * @description watches historical candlestick data containing the open, high, low, close price, and the volume of a market
 * @see https://docs.cdp.coinbase.com/api-reference/coinbase-deribit-app-api/websocket/market-data/charttradesinstrument_nameresolution
 * @see https://docs.deribit.com/subscriptions/market-data/charttradesinstrument_nameresolution
 * @param {string} symbol unified symbol of the market to fetch ccxt.OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.route] auto (default), deribit, or coinbase; overrides options.route
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Coinbaseinternational) WatchOHLCVAsync(symbol string, optionalArgs ...any) <-chan ccxt.AsyncResult[[]ccxt.OHLCV] {
	ch := make(chan ccxt.AsyncResult[[]ccxt.OHLCV], 1)
	go this.watchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinbaseinternational) watchOHLCVBody(ch chan ccxt.AsyncResult[[]ccxt.OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var timeframe string = ccxt.GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("watchOHLCV", params)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolResolved any = this.Symbol(symbol)

	r1 := <-this.WatchOHLCVForSymbolsAsync([]any{[]any{symbolResolved, timeframe}}, since, limit, paramsResolved)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var ohlcvs map[string]any = ccxt.StructResultMap(r1.Value, ccxt.OHLCVForSymbolsMapToMap)

	var resolved []any
	switch resolvedBox := ccxt.GetValue(ccxt.GetValue(ohlcvs, symbolResolved), timeframe).(type) {
	case []any:
		resolved = resolvedBox
	case ccxt.IArrayCache:
		resolved = resolvedBox.ToArray()
	case nil:
	default:
		panic(ccxt.ExchangeError("resolved value is not []any"))
	}
	ch <- ccxt.AsyncResult[[]ccxt.OHLCV]{Value: ccxt.OHLCVsFromList(resolved)}
	return nil
}

/**
 * @method
 * @name coinbaseinternational#watchOHLCVForSymbols
 * @description watches historical candlestick data for multiple markets and timeframes
 * @see https://docs.cdp.coinbase.com/api-reference/coinbase-deribit-app-api/websocket/market-data/charttradesinstrument_nameresolution
 * @see https://docs.deribit.com/subscriptions/market-data/charttradesinstrument_nameresolution
 * @param {string[][]} symbolsAndTimeframes array of arrays containing unified symbols and timeframes
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.route] auto (default), deribit, or coinbase; overrides options.route
 * @returns {object} a dictionary of ccxt.OHLCV arrays indexed by symbol and timeframe
 */
func (this *Coinbaseinternational) WatchOHLCVForSymbolsAsync(symbolsAndTimeframes any, optionalArgs ...any) <-chan ccxt.AsyncResult[map[string]map[string][]ccxt.OHLCV] {
	ch := make(chan ccxt.AsyncResult[map[string]map[string][]ccxt.OHLCV], 1)
	go this.watchOHLCVForSymbolsBody(ch, symbolsAndTimeframes, optionalArgs...)
	return ch
}
func (this *Coinbaseinternational) watchOHLCVForSymbolsBody(ch chan ccxt.AsyncResult[map[string]map[string][]ccxt.OHLCV], symbolsAndTimeframes any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("watchOHLCVForSymbols", params)
	var symbolsAndTimeframesLength int = ccxt.GetArrayLength(symbolsAndTimeframes)
	if (symbolsAndTimeframesLength == 0) || !ccxt.IsArray(ccxt.GetValue(symbolsAndTimeframes, 0)) {
		panic(ccxt.ArgumentsRequired(this.Id + " watchOHLCVForSymbols() requires an array of symbols and timeframes, like [['BTC/USDC', '1m']]"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var channels []any = []any{}
	for i := 0; i < symbolsAndTimeframesLength; i++ {
		var current any = ccxt.GetValue(symbolsAndTimeframes, i)
		var currentTimeframe *string = this.SafeString(current, 1)
		var resolution *string = this.SafeString(this.Timeframes, currentTimeframe, currentTimeframe)
		var market map[string]any = this.Market(this.SafeString(current, 0))
		channels = append(channels, ccxt.Add("chart.trades."+*this.SafeString(market, "id", "")+".", resolution))
	}

	r1 := <-this.SubscribeAsync(channels, channels, false, paramsResolved)
	if r1.Err != nil {
		panic(r1.Err)
	}
	resolved := r1.Value
	var symbol *string = this.SafeString(resolved, 0)
	var timeframe *string = this.SafeString(resolved, 1)
	var ohlcv any = this.SafeValue(resolved, 2)
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(ohlcv).GetLimit(symbol, limit)
	}
	var filtered []any = this.FilterBySinceLimit(ohlcv, since, limitResolved, 0, true)

	ch <- ccxt.AsyncResult[map[string]map[string][]ccxt.OHLCV]{Value: ccxt.OHLCVForSymbolsMapFromMap(this.CreateOHLCVObject(symbol, timeframe, filtered))}
	return nil
}

